const fs = require('fs');

const iconBase64 = '';

fs.mkdirSync('images', { recursive: true });
fs.writeFileSync('images/home-button.png', Buffer.from(iconBase64, 'base64'));

const indexPath = 'index.html';
let html = fs.readFileSync(indexPath, 'utf8');
const oldNav = `      <nav class="main-nav" aria-label="주요 메뉴">
        <button class="nav-item is-active" type="button" data-section="savior">구원자</button>
        <button class="nav-item" type="button" data-section="arcana">아르카나</button>
        <button class="nav-item" type="button" data-section="journey">여정</button>
        <button class="nav-item" type="button" data-section="equipment">장비</button>
      </nav>`;
const newNav = `      <nav class="main-nav" aria-label="주요 메뉴">
        <button class="nav-item is-active" type="button" data-section="savior">구원자</button>
        <button class="nav-item" type="button" data-section="arcana">아르카나</button>
        <button class="nav-item" type="button" data-section="equipment">장비</button>
        <button class="nav-item" type="button" data-section="journey">여정</button>
      </nav>`;
if (html.includes(oldNav)) html = html.replace(oldNav, newNav);
if (!html.includes(newNav)) throw new Error('Could not verify reordered navigation');
html = html.replace(/src="\.\/images\/home-button\.png(?:\?v=[^"]*)?"/, 'src="./images/home-button.png?v=20260915c"');
fs.writeFileSync(indexPath, html, 'utf8');

const stylePath = 'styles.css';
let css = fs.readFileSync(stylePath, 'utf8');
css = css.replace('  --muted: #657187;\n  --faint: #8993a4;', '  --muted: #4f5d73;\n  --faint: #6f7c90;');
fs.writeFileSync(stylePath, css, 'utf8');

console.log('UI patch applied');
